document.addEventListener("DOMContentLoaded",()=>{const e=[{label:"Train Type",value:"Luxury Tourist Train"},{label:"Coaches",value:"23"},{label:"Inaugurated",value:"March 2010"},{label:"Major Regions",value:"Rajasthan, UP, MP"}],a=document.getElementById("quick-facts-container");a&&e.forEach(e=>{const n=document.createElement("div");n.className="fact-card",n.innerHTML=`\n                <div class="fact-label">${e.label}</div>\n                <div class="fact-value">${e.value}</div>\n            `,a.appendChild(n)});const n=[{year:"2010",title:"Inaugural Run",description:"The Maharajas' Express was launched in March 2010 as a joint venture between IRCTC and Cox and Kings India."},{year:"2011",title:"Exclusive IRCTC Operation",description:"The joint venture ended, and IRCTC took over the complete operation and management of the train."},{year:"2012-2018",title:"World's Leading Luxury Train",description:"Won the prestigious 'World's Leading Luxury Train' award at the World Travel Awards for seven consecutive years."}],i=document.getElementById("timeline-container");i&&n.forEach(e=>{const a=document.createElement("div");a.className="timeline-item",a.tabIndex=0,a.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,i.appendChild(a)});const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>t.observe(e));const r=[{icon:"👑",title:"Presidential Suite (Navratana)",description:"An entire carriage comprising two bedrooms, a living area, and a private bathroom with a bathtub. The pinnacle of railway luxury."},{icon:"💎",title:"Suite & Junior Suite",description:"Spacious suites equipped with large panoramic windows, en-suite bathrooms, and dedicated butler service."},{icon:"🛏️",title:"Deluxe Cabin",description:"Luxurious twin/double bed cabins featuring climate control, LCD TVs, and high-end toiletries."},{icon:"🖼️",title:"Regal Interiors",description:"Each coach is named after a precious stone (like Moti, Heera) and decorated to reflect the opulence of Indian royalty."}],s=document.getElementById("design-container");s&&r.forEach(e=>{const a=document.createElement("div");a.className="design-card",a.tabIndex=0,a.innerHTML=`\n                <div class="card-icon" aria-hidden="true">${e.icon}</div>\n                <h3 class="card-title">${e.title}</h3>\n                <p class="card-desc">${e.description}</p>\n            `,s.appendChild(a)});const o=[{name:"Heritage of India",duration:"6 Nights / 7 Days",start:"Mumbai",end:"Delhi",destinations:["Udaipur","Jodhpur","Bikaner","Jaipur","Ranthambore","Agra"]},{name:"Indian Panorama",duration:"6 Nights / 7 Days",start:"Delhi",end:"Delhi",destinations:["Jaipur","Ranthambore","Fatehpur Sikri","Agra","Orchha","Khajuraho","Varanasi"]},{name:"The Indian Splendour",duration:"6 Nights / 7 Days",start:"Delhi",end:"Mumbai",destinations:["Agra","Ranthambore","Jaipur","Bikaner","Jodhpur","Udaipur"]},{name:"Treasures of India",duration:"3 Nights / 4 Days",start:"Delhi",end:"Delhi",destinations:["Agra","Ranthambore","Jaipur"]}],d=document.getElementById("itineraries-container");d&&o.forEach(e=>{const a=document.createElement("div");a.className="itinerary-card",a.tabIndex=0;const n=e.destinations.map(e=>`<span>${e}</span>`).join("");a.innerHTML=`\n                <h3 class="card-title">${e.name}</h3>\n                <div class="itinerary-meta">${e.duration} | ${e.start} ➝ ${e.end}</div>\n                <div class="route-stations">\n                    ${n}\n                </div>\n            `,d.appendChild(a)});const c=[{icon:"🏰",title:"Agra & Taj Mahal",description:"Experience the iconic Taj Mahal, Agra Fort, and a Champagne breakfast overlooking the monument."},{icon:"🐅",title:"Ranthambore Safari",description:"Thrilling jeep safaris in Ranthambore National Park to spot the elusive Bengal Tiger."},{icon:"🐘",title:"Jaipur - The Pink City",description:"Explore the Amber Fort, City Palace, and enjoy exclusive elephant polo matches."},{icon:"🌅",title:"Varanasi & River Ganges",description:"Witness the mesmerizing Ganga Aarti ceremony from a private boat ride at dusk."}],l=document.getElementById("destinations-container");l&&c.forEach(e=>{const a=document.createElement("div");a.className="dest-card",a.tabIndex=0,a.innerHTML=`\n                <div class="card-icon" aria-hidden="true">${e.icon}</div>\n                <h3 class="card-title">${e.title}</h3>\n                <p class="card-desc">${e.description}</p>\n            `,l.appendChild(a)});const u=[{icon:"🍽️",title:"Mayur Mahal & Rang Mahal",description:"Two exquisite fine-dining restaurants serving Indian and international cuisines on gold-plated cutlery."},{icon:"🍷",title:"Rajah Club & Safari Bar",description:"Two dedicated lounge bars offering the finest wines, spirits, and a relaxed club atmosphere."},{icon:"🔔",title:"Personal Valet Service",description:"A dedicated 24-hour butler assigned to every carriage to cater to all passenger needs."},{icon:"🛡️",title:"Modern Safety & Tech",description:"Equipped with pneumatic suspension for ride comfort, CCTV cameras, and electronic safes in every cabin."}],h=document.getElementById("facilities-container");h&&u.forEach(e=>{const a=document.createElement("div");a.className="facility-card",a.tabIndex=0,a.innerHTML=`\n                <div class="card-icon" aria-hidden="true">${e.icon}</div>\n                <h3 class="card-title">${e.title}</h3>\n                <p class="card-desc">${e.description}</p>\n            `,h.appendChild(a)});const p=["The Maharajas' Express Presidential Suite, spanning an entire carriage, is a first of its kind in international luxury trains.","The train has a total passenger capacity of only 88 guests, ensuring an exclusive and personalized experience.","It features an onboard water filtration plant to provide safe, clean drinking water to all guests."],m=document.getElementById("trivia-container");m&&p.forEach(e=>{const a=document.createElement("div");a.className="trivia-card",a.tabIndex=0,a.innerHTML=`<p>${e}</p>`,m.appendChild(a)})});